#include "optimizer.hpp"
#include <limits>
#include <unordered_map>
namespace minic { namespace {
bool safeBinary(IROp op,std::int64_t a,std::int64_t b,std::int64_t& out){using L=std::numeric_limits<std::int64_t>;switch(op){case IROp::Add: if((b>0&&a>L::max()-b)||(b<0&&a<L::min()-b))return false;out=a+b;return true;case IROp::Sub:if((b<0&&a>L::max()+b)||(b>0&&a<L::min()+b))return false;out=a-b;return true;case IROp::Mul: if(a==0||b==0){out=0;return true;}if((a==-1&&b==L::min())||(b==-1&&a==L::min()))return false; if(a>0?(b>0?a>L::max()/b:b<L::min()/a):(b>0?a<L::min()/b:a!=0&&b<L::max()/a))return false;out=a*b;return true;case IROp::Div:if(b==0||(a==L::min()&&b==-1))return false;out=a/b;return true;default:return false;}}
}
std::vector<IRInstruction> optimizeConstants(const std::vector<IRInstruction>& input){std::vector<IRInstruction> out;std::unordered_map<std::string,std::int64_t> constants;for(auto i:input){if(i.op==IROp::LoadConst){constants[i.dest]=i.value;out.push_back(i);continue;}if(i.op==IROp::LoadVar){constants.erase(i.dest);out.push_back(i);continue;}if(i.op==IROp::Neg){auto it=constants.find(i.left);std::int64_t v=0;if(it!=constants.end()&&it->second!=std::numeric_limits<std::int64_t>::min()){v=-it->second;i.op=IROp::LoadConst;i.value=v;i.left.clear();constants[i.dest]=v;}else constants.erase(i.dest);out.push_back(i);continue;}if(i.op==IROp::Add||i.op==IROp::Sub||i.op==IROp::Mul||i.op==IROp::Div){auto a=constants.find(i.left),b=constants.find(i.right);std::int64_t v=0;if(a!=constants.end()&&b!=constants.end()&&safeBinary(i.op,a->second,b->second,v)){i.op=IROp::LoadConst;i.value=v;i.left.clear();i.right.clear();constants[i.dest]=v;}else constants.erase(i.dest);out.push_back(i);continue;}if(i.op==IROp::Store){out.push_back(i);continue;}out.push_back(i);}return out;}
}
